<?php
require 'common.php';require_admin();$rows=products();usort($rows,fn($a,$b)=>product_quality($a)<=>product_quality($b));$avg=$rows?round(array_sum(array_map('product_quality',$rows))/count($rows)):0;admin_head('مركز جودة البيانات');?>
<section class="metric-grid"><?php metric('متوسط الجودة',$avg.'%','جميع المنتجات','green');metric('أقل من 60%',(string)count(array_filter($rows,fn($p)=>product_quality($p)<60)),'تحتاج تدخل','red');metric('بدون مصدر',(string)count(array_filter($rows,fn($p)=>empty($p['source_url']))),'مطلوب تحقق','silver');metric('بدون صورة',(string)count(array_filter($rows,fn($p)=>empty($p['image']))),'تحسين بصري','blue');?></section>
<section class="panel"><div class="panel-head"><div><span>DATA GOVERNANCE</span><h2>تدقيق المنتجات</h2></div><p>الهدف: اسم + موديل + فئة + وصف + مواصفات + مصدر + صورة + ثقة.</p></div><div class="quality-audit"><?php foreach($rows as$p):$score=product_quality($p);$missing=[];foreach(['brand'=>'العلامة','model'=>'الموديل','category'=>'الفئة','description'=>'الوصف','source_url'=>'المصدر','image'=>'الصورة'] as$k=>$label)if(empty($p[$k]))$missing[]=$label;if(empty($p['specs']))$missing[]='المواصفات';?><article><div class="qa-score <?=$score>=80?'good':($score>=60?'warn':'bad')?>"><b><?=$score?>%</b><span>QUALITY</span></div><div class="qa-main"><h3><?=e((string)($p['name']??''))?></h3><p><?=e((string)($p['brand']??''))?> · <?=e((string)($p['model']??''))?></p><div class="missing-tags"><?php if($missing):foreach($missing as$m):?><span><?=e($m)?></span><?php endforeach;else:?><span class="complete">بيانات مكتملة</span><?php endif;?></div></div><a href="products.php?q=<?=urlencode((string)($p['name']??''))?>">فتح المنتج ←</a></article><?php endforeach;?><?php if(!$rows):?><p class="muted-cell">لا توجد منتجات للتدقيق.</p><?php endif;?></div></section>
<?php admin_foot();?>